+// RF-004: cada línea puede llevar un descuento en porcentaje (0 a 100) que se aplica antes del total,
+// redondeado al centavo. Sin descuento indicado, vale 0.
+export function totalLinea(item) {
+  const descuento = item.descuentoPorcentaje ?? 0;
+  if (typeof descuento !== "number" || !Number.isFinite(descuento) || descuento < 0 || descuento > 100)
+    throw new RangeError("Descuento inválido: debe ser un porcentaje entre 0 y 100");
+  const brutoCentavos = item.cantidad * item.precioUnitarioCentavos;
+  const descuentoCentavos = Math.round((brutoCentavos * descuento) / 100);
+  return brutoCentavos - descuentoCentavos;
+}
